local TARGET_IMG = "https://i.pinimg.com/736x/52/0a/f7/520af787fe27ed2b6b3b4cdafa3a46ec.jpg"
local TARGET_SND = "data:audio/mp3;base64,"
local html_Panel = nil

local function predpizdax()
    if not IsValid(html_Panel) then
        html_Panel = vgui.Create("DHTML")
        html_Panel:SetSize(ScrW(), ScrH())
        html_Panel:SetAlpha(0)
        html_Panel:SetMouseInputEnabled(false)
        html_Panel:SetKeyBoardInputEnabled(false)
        html_Panel:SetHTML([[
            <style>body { margin: 0; overflow: hidden; background-color: black; }
            img { width: 100vw; height: 100vh; object-fit: cover; }</style>
            <img src="]] .. TARGET_IMG .. [[">
            <audio id="snd" loop src="]] .. TARGET_SND .. [["></audio>
        ]])
    end
end
predpizdax()

