local function sss()
    local startTime = CurTime()
    local duration = 5
    local triggered = false
    
    hook.Add("HUDShouldDraw", "Daaaaa", function() return false end)
    
    hook.Add("RenderScreenspaceEffects", "Drochilbabke", function()
        draw.RoundedBox(0, 0, 0, ScrW(), ScrH(), Color(0, 0, 0, 255))
        
        if IsValid(html_Panel) then
            if math.sin(CurTime() * 350) > 0 then
                html_Panel:SetAlpha(255)
            else
                html_Panel:SetAlpha(0)
            end
        end

        local elapsed = CurTime() - startTime
        local timeLeft = math.max(0, math.Round(duration - elapsed, 2))
        
        draw.SimpleText("nigga: " .. timeLeft .. "s", "DermaLarge", ScrW()/2, ScrH()/2, Color(255, 0, 0), TEXT_ALIGN_CENTER)
		
		if timeLeft <= 0.1 and not triggered then
            triggered = true
		
            timer.Simple(0.1, function()
    if IsValid(html_Panel) then
        html_Panel:RunJavascript("document.getElementById('snd').play();")
    end
    cuminpinetration()

            end)
        end
    end)
end

